export enum SourceType {
  AUDIO = 'AUDIO',
  TEXT = 'TEXT'
}

export interface Source {
  id: string;
  type: SourceType;
  content: string;
  mimeType?: string;
  name: string;
  transcription?: string;
  isProcessing: boolean;
}

export interface ChapterOutline {
  chapterNumber: number;
  title: string;
  summary: string;
}

export type WritingStyle = 'standard' | 'literary' | 'humorous' | 'technical' | 'simple';

export interface BookOutline {
  title: string;
  description: string;
  chapters: ChapterOutline[];
  coverImage?: string;
}

export interface ChapterContent {
  chapterNumber: number;
  title: string;
  content: string;
  isGenerating: boolean;
}

export interface Character {
  id: string;
  name: string;
  role: string; // e.g. Protagonist, Antagonist
  description: string;
}

export interface Setting {
  id: string;
  name: string;
  description: string;
}

export interface SeriesContext {
  characters: Character[];
  settings: Setting[];
}

export interface BookSeries {
  id: string;
  title: string;
  description: string;
  context: SeriesContext;
  bookIds: string[]; // IDs of projects in this series
  lastModified: number;
}

export interface BookProject {
  id: string;
  seriesId?: string; // Optional link to a series
  title: string;
  lastModified: number;
  sources: Source[];
  outline: BookOutline | null;
  chapters: ChapterContent[];
