## services/gemini.ts

Updated generation logic to include Series Context (Characters/Settings) in the prompt to ensure continuity.

```typescript
import { GoogleGenAI, Type, Schema } from "@google/genai";
import { BookOutline, ChapterOutline, Source, SourceType, WritingStyle, SeriesContext } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Models
const MODEL_FAST = 'gemini-2.5-flash';
const MODEL_SMART = 'gemini-3-pro-preview';
const MODEL_IMAGE = 'gemini-2.5-flash-image';

export const transcribeAudio = async (base64Audio: string, mimeType: string): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: MODEL_FAST,
      contents: {
        parts: [
          {
            inlineData: {
              data: base64Audio,
              mimeType: mimeType
            }
          },
          {
            text: "Transcribe the following audio precisely. Return only the transcript text."
          }
        ]
      }
    });
    return response.text || "";
  } catch (error) {
    console.error("Transcription error:", error);
    throw new Error("Failed to transcribe audio.");
  }
};

export const generateOutline = async (sources: Source[], seriesContext?: SeriesContext): Promise<BookOutline> => {
  // Aggregate context
  let context = "";

  for (const source of sources) {
    if (source.type === SourceType.TEXT) {
      context += `\n\n--- Source: ${source.name} (Notes) ---\n${source.content}`;
    } else if (source.type === SourceType.AUDIO && source.transcription) {
      context += `\n\n--- Source: ${source.name} (Transcript) ---\n${source.transcription}`;
    }
  }

  let seriesPrompt = "";
  if (seriesContext) {
    const chars = seriesContext.characters.map(c => `- ${c.name} (${c.role}): ${c.description}`).join('\n');
    const locs = seriesContext.settings.map(s => `- ${s.name}: ${s.description}`).join('\n');
    seriesPrompt = `\n\nEXISTING SERIES CONTEXT (Must be consistent with this):\nCHARACTERS:\n${chars}\n\nSETTINGS:\n${locs}\n`;
  }

  const schema: Schema = {
    type: Type.OBJECT,
    properties: {
      title: { type: Type.STRING, description: "A creative and engaging title for the book." },
      description: { type: Type.STRING, description: "A synopsis of the book." },
      chapters: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            chapterNumber: { type: Type.INTEGER },
            title: { type: Type.STRING },
            summary: { type: Type.STRING, description: "Detailed plot points to cover in this chapter." }
          },
          required: ["chapterNumber", "title", "summary"]
        }
      }
    },
    required: ["title", "description", "chapters"]
  };

  try {
    const response = await ai.models.generateContent({
      model: MODEL_SMART,
      contents: `You are a professional book editor. Analyze the following source materials (notes and transcripts) and create a comprehensive book outline.

      The source material is unstructured. Your job is to find the narrative arc, themes, and key events to structure a cohesive non-fiction or fiction book (depending on the content).
      ${seriesPrompt}
      ${context}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
        thinkingConfig: { thinkingBudget: 2048 }
      }
    });

    if (!response.text) throw new Error("No response generated");
    return JSON.parse(response.text) as BookOutline;
  } catch (error) {
    console.error("Outline generation error:", error);
    throw new Error("Failed to generate outline.");
  }
};

export const generateImage = async (prompt: string, aspectRatio: "1:1" | "3:4" | "4:3" | "16:9" | "9:16" = "1:1"): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: MODEL_IMAGE,
      contents: {
        parts: [
          { text: prompt }
        ]
      },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio
        }
      }
    });

    for (const candidate of response.candidates || []) {
      for (const part of candidate.content?.parts || []) {
        if (part.inlineData && part.inlineData.data) {
          return part.inlineData.data;
        }
      }
    }

    throw new Error("No image data found in response");
  } catch (error) {
    console.error("Image generation error:", error);
    throw new Error("Failed to generate image.");
  }
};

export const writeChapter = async (
  chapter: ChapterOutline,
  outline: BookOutline,
  sources: Source[],
  style: WritingStyle = 'standard',
  seriesContext?: SeriesContext
): Promise<string> => {
   let sourceContext = "";
   for (const source of sources) {
     const text = source.type === SourceType.TEXT ? source.content : source.transcription;
     sourceContext += `\n[Source: ${source.name}]: ${text?.slice(0, 5000)}...`;
   }

   let seriesPrompt = "";
   if (seriesContext) {
     const chars = seriesContext.characters.map(c => `- ${c.name} (${c.role}): ${c.description}`).join('\n');
     const locs = seriesContext.settings.map(s => `- ${s.name}: ${s.description}`).join('\n');
     seriesPrompt = `\n\nCRITICAL SERIES CONTEXT (Ensure consistency with these details):\nCHARACTERS:\n${chars}\n\nSETTINGS:\n${locs}\n`;
   }

   const styleInstructions: Record<string, string> = {
     'standard': 'Write in a clear, engaging, and professional manner.',
     'literary': 'Use rich descriptions, metaphors, and elevated prose.',
     'humorous': 'Be witty, light-hearted, and entertaining.',
     'technical': 'Be precise, factual, and educational.',
     'simple': 'Use simple vocabulary and direct sentence structures for high readability.'
   };

   try {
     const response = await ai.models.generateContent({
       model: MODEL_SMART,
       contents: `You are a best-selling author. Write the full content for Chapter ${chapter.chapterNumber}: "${chapter.title}".

       Book Title: ${outline.title}
       Book Description: ${outline.description}

       Chapter Summary/Goals: ${chapter.summary}

       Source Material Context:
       ${sourceContext}

       ${seriesPrompt}

       Writing Style: ${styleInstructions[style] || styleInstructions['standard']}

       Instructions:
       - Write in an engaging, high-quality literary style matching the requested tone.
       - Ensure continuity with the overall book theme.
       - Use the source material as the factual/narrative basis but expand creatively to flow well as a book.
       - Format with Markdown (headers, paragraphs).`,
       config: {
         thinkingConfig: { thinkingBudget: 4096 }
       }
     });

     return response.text || "";
   } catch (error) {
     console.error("Chapter writing error:", error);
     throw new Error(`Failed to write chapter ${chapter.chapterNumber}`);
   }
};
```

## components/SeriesBible.tsx

New component for managing persistent characters and settings.

```typescript
import React, { useState } from 'react';
import { SeriesContext, Character, Setting } from '../types';
import { Plus, Users, MapPin, Trash2, Save, X } from 'lucide-react';

interface SeriesBibleProps {
  context: SeriesContext;
  onUpdate: (context: SeriesContext) => void;
}

export const SeriesBible: React.FC<SeriesBibleProps> = ({ context, onUpdate }) => {
  const [activeTab, setActiveTab] = useState<'CHARACTERS' | 'SETTINGS'>('CHARACTERS');
  const [isAdding, setIsAdding] = useState(false);

  // Temporary state for new items
  const [newItemName, setNewItemName] = useState('');
  const [newItemRole, setNewItemRole] = useState(''); // Only for chars
  const [newItemDesc, setNewItemDesc] = useState('');

  const handleAddItem = () => {
    if (!newItemName.trim()) return;

    if (activeTab === 'CHARACTERS') {
      const newChar: Character = {
        id: crypto.randomUUID(),
        name: newItemName,
        role: newItemRole,
        description: newItemDesc
      };
      onUpdate({
        ...context,
        characters: [...context.characters, newChar]
      });
    } else {
      const newSetting: Setting = {
        id: crypto.randomUUID(),
        name: newItemName,
        description: newItemDesc
      };
      onUpdate({
        ...context,
        settings: [...context.settings, newSetting]
      });
    }

    // Reset
    setNewItemName('');
    setNewItemRole('');
    setNewItemDesc('');
    setIsAdding(false);
  };

  const handleDelete = (id: string, type: 'CHAR' | 'SET') => {
    if (type === 'CHAR') {
      onUpdate({
        ...context,
        characters: context.characters.filter(c => c.id !== id)
      });
    } else {
      onUpdate({
        ...context,
        settings: context.settings.filter(s => s.id !== id)
      });
    }
  };

  return (
    <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden h-full flex flex-col">
      <div className="p-6 bg-slate-50 border-b border-slate-200">
         <h2 className="font-serif font-bold text-slate-900 text-xl mb-1">Series Bible</h2>
         <p className="text-xs text-slate-500">Persistent context for all books in this series.</p>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200">
        <button 
          onClick={() => { setActiveTab('CHARACTERS'); setIsAdding(false); }}
          className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider flex items-center justify-center gap-2 ${activeTab === 'CHARACTERS' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
        >
          <Users size={14} /> Characters
        </button>
        <button 
          onClick={() => { setActiveTab('SETTINGS'); setIsAdding(false); }}
          className={`flex-1 py-3 text-xs font-bold uppercase tracking-wider flex items-center justify-center gap-2 ${activeTab === 'SETTINGS' ? 'bg-white text-blue-600 border-b-2 border-blue-600' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}
        >
          <MapPin size={14} /> Settings
        </button>
      </div>

      <div className="p-4 flex-1 overflow-y-auto">
        {isAdding ? (
          <div className="bg-slate-50 p-4 rounded-lg border border-blue-200 animate-in fade-in zoom-in-95">
            <div className="flex justify-between items-center mb-4">
               <h3 className="text-xs font-bold text-blue-600 uppercase">New {activeTab === 'CHARACTERS' ? 'Character' : 'Setting'}</h3>
               <button onClick={() => setIsAdding(false)}><X size={16} className="text-slate-400 hover:text-red-500"/></button>
            </div>
            <div className="space-y-3">
              <input 
                placeholder="Name" 
                value={newItemName}
                onChange={e => setNewItemName(e.target.value)}
                className="w-full p-2 text-sm border border-slate-300 rounded focus:ring-2 focus:ring-blue-100 outline-none"
              />
              {activeTab === 'CHARACTERS' && (
                <input 
                  placeholder="Role (e.g. Protagonist)" 
                  value={newItemRole}
                  onChange={e => setNewItemRole(e.target.value)}
                  className="w-full p-2 text-sm border border-slate-300 rounded focus:ring-2 focus:ring-blue-100 outline-none"
                />
              )}
              <textarea 
                placeholder="Description & Notes" 
                value={newItemDesc}
                onChange={e => setNewItemDesc(e.target.value)}
                rows={3}
                className="w-full p-2 text-sm border border-slate-300 rounded focus:ring-2 focus:ring-blue-100 outline-none resize-none"
              />
              <button 
                onClick={handleAddItem}
                className="w-full py-2 bg-blue-600 text-white rounded text-sm font-bold hover:bg-blue-500 transition-colors flex items-center justify-center gap-2"
              >
                <Save size={14} /> Save to Bible
              </button>
            </div>
          </div>
        ) : (
          <button 
            onClick={() => setIsAdding(true)}
            className="w-full py-3 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 font-bold text-xs uppercase hover:border-blue-300 hover:text-blue-600 hover:bg-blue-50 transition-all mb-4 flex items-center justify-center gap-2"
          >
            <Plus size={14} /> Add {activeTab === 'CHARACTERS' ? 'Character' : 'Setting'}
          </button>
        )}

        <div className="space-y-3">
          {activeTab === 'CHARACTERS' ? (
            context.characters.map(char => (
              <div key={char.id} className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm group hover:border-blue-200 transition-colors">
                <div className="flex justify-between items-start">
                  <div>
                    <h4 className="font-bold text-slate-800 text-sm">{char.name}</h4>
                    <span className="text-[10px] font-bold text-blue-500 uppercase tracking-wide bg-blue-50 px-1.5 py-0.5 rounded">{char.role}</span>
                  </div>
                  <button onClick={() => handleDelete(char.id, 'CHAR')} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Trash2 size={14} />
                  </button>
                </div>
                <p className="text-xs text-slate-500 mt-2 line-clamp-3">{char.description}</p>
              </div>
            ))
          ) : (
            context.settings.map(setting => (
              <div key={setting.id} className="bg-white p-3 rounded-lg border border-slate-200 shadow-sm group hover:border-blue-200 transition-colors">
                <div className="flex justify-between items-start">
                  <h4 className="font-bold text-slate-800 text-sm">{setting.name}</h4>
                  <button onClick={() => handleDelete(setting.id, 'SET')} className="text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Trash2 size={14} />
                  </button>
                </div>
                <p className="text-xs text-slate-500 mt-2 line-clamp-3">{setting.description}</p>
              </div>
            ))
          )}

          {!isAdding && ((activeTab === 'CHARACTERS' && context.characters.length === 0) || (activeTab === 'SETTINGS' && context.settings.length === 0)) && (
             <div className="text-center text-slate-400 text-xs py-4 italic">Nothing added yet.</div>
          )}
        </div>
      </div>
    </div>
  );
};
```

## components/SeriesView.tsx

New component to manage a series.

```typescript
import React from 'react';
import { BookSeries, BookProject, SeriesContext } from '../types';
import { SeriesBible } from './SeriesBible';
import { ChevronLeft, Plus, BookOpen, Clock, Trash2 } from 'lucide-react';

interface SeriesViewProps {
  series: BookSeries;
  projects: BookProject[]; // All projects, filter inside or pass filtered
  onUpdateSeries: (series: BookSeries) => void;
  onCreateBookInSeries: (seriesId: string) => void;
  onSelectProject: (project: BookProject) => void;
  onDeleteProject: (id: string, e: React.MouseEvent) => void;
  onBack: () => void;
}

export const SeriesView: React.FC<SeriesViewProps> = ({
  series,
  projects,
  onUpdateSeries,
  onCreateBookInSeries,
  onSelectProject,
  onDeleteProject,
  onBack
}) => {
  // Filter projects belonging to this series
  const seriesBooks = projects.filter(p => p.seriesId === series.id);

  const handleUpdateContext = (newContext: SeriesContext) => {
    onUpdateSeries({
      ...series,
      context: newContext,
      lastModified: Date.now()
    });
  };

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric'
    });
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col">
       {/* Header */}
       <div className="bg-white border-b border-slate-200 sticky top-0 z-10">
         <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <button 
                onClick={onBack}
                className="p-2 -ml-2 text-slate-400 hover:text-blue-700 hover:bg-blue-50 rounded-lg transition-colors"
              >
                <ChevronLeft size={20} />
              </button>
              <div>
                <h1 className="font-serif font-bold text-xl text-slate-900 leading-none">{series.title}</h1>
                <span className="text-xs text-slate-500 font-medium">Series Dashboard</span>
              </div>
            </div>

            <button 
              onClick={() => onCreateBookInSeries(series.id)}
              className="bg-blue-600 hover:bg-blue-500 text-white px-4 py-2 rounded-lg font-medium text-sm flex items-center gap-2 shadow-sm"
            >
              <Plus size={16} />
              Add Book to Series
            </button>
         </div>
       </div>

       <div className="flex-1 max-w-7xl mx-auto w-full px-6 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

          {/* Main Content: Books List */}
          <div className="lg:col-span-8 space-y-6">
             <div className="flex items-center justify-between">
                <h2 className="text-lg font-bold font-serif text-slate-800">Books in Series</h2>
                <span className="text-xs font-bold bg-slate-200 text-slate-600 px-2 py-1 rounded-full">{seriesBooks.length}</span>
             </div>

             {seriesBooks.length === 0 ? (
               <div className="text-center py-16 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50">
                  <p className="text-slate-400 font-medium mb-4">No books in this series yet.</p>
                  <button onClick={() => onCreateBookInSeries(series.id)} className="text-blue-600 font-bold hover:underline">Create Book 1</button>
               </div>
             ) : (
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {seriesBooks.map((book, index) => (
                   <div 
                     key={book.id}
                     onClick={() => onSelectProject(book)}
                     className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md hover:border-blue-300 cursor-pointer group relative overflow-hidden transition-all"
                   >
                     <div className="absolute top-0 right-0 bg-slate-100 text-slate-500 text-[10px] font-bold px-2 py-1 rounded-bl-lg">
                       Book {index + 1}
                     </div>

                     <div className="mb-4">
                       <h3 className="font-serif font-bold text-lg text-slate-900 group-hover:text-blue-700 transition-colors line-clamp-1">{book.title}</h3>
                       <div className="flex items-center gap-2 text-xs text-slate-400 mt-1">
                         <Clock size={12} /> {formatDate(book.lastModified)}
                       </div>
                     </div>

                     <div className="flex justify-between items-center pt-4 border-t border-slate-100">
                        <span className="text-xs font-semibold px-2 py-1 bg-blue-50 text-blue-700 rounded-md">
                          {book.chapters.length} Chapters
                        </span>
                        <button 
                           onClick={(e) => onDeleteProject(book.id, e)}
                           className="p-1.5 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded transition-colors"
                        >
                          <Trash2 size={14} />
                        </button>
                     </div>
                   </div>
                 ))}
               </div>
             )}
          </div>

          {/* Sidebar: Bible */}
          <div className="lg:col-span-4 h-[calc(100vh-140px)] sticky top-24">
             <SeriesBible context={series.context} onUpdate={handleUpdateContext} />
          </div>

       </div>
    </div>
  );
};
```

## components/Dashboard.tsx

Updated with Tabs and Series Creation logic.

```typescript
import React, { useState } from 'react';
import { BookProject, BookSeries } from '../types';
import { Plus, Book, Clock, Trash2, Download, Layers, FolderOpen } from 'lucide-react';

interface DashboardProps {
  projects: BookProject[];
  series: BookSeries[];
  onCreateProject: () => void;
  onCreateSeries: (title: string) => void;
  onSelectProject: (project: BookProject) => void;
  onSelectSeries: (series: BookSeries) => void;
  onDeleteProject: (id: string, e: React.MouseEvent) => void;
  onDeleteSeries: (id: string, e: React.MouseEvent) => void;
}

export const Dashboard: React.FC<DashboardProps> = ({ 
  projects, 
  series,
  onCreateProject, 
  onCreateSeries,
  onSelectProject,
  onSelectSeries,
  onDeleteProject,
  onDeleteSeries
}) => {
  const [activeTab, setActiveTab] = useState<'ALL' | 'SERIES' | 'STANDALONE'>('ALL');
  const [isCreatingSeries, setIsCreatingSeries] = useState(false);
  const [newSeriesTitle, setNewSeriesTitle] = useState('');

  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString('en-US', {
      month: 'long',
      day: 'numeric',
      year: 'numeric'
    });
  };

