```typescript
import React, { useState, useRef, useEffect } from 'react';
import { ChapterContent, BookOutline } from '../types';
import { ChevronLeft, ChevronRight, Loader2, FileText, Share2, Printer, Download, Edit3, Check, X, RefreshCcw } from 'lucide-react';
import ReactMarkdown from 'react-markdown';

interface BookReaderProps {
  outline: BookOutline;
  chapters: ChapterContent[];
  onUpdateChapter: (chapterIndex: number, newContent: string) => void;
  onRegenerateChapter: (chapterIndex: number) => void;
}

export const BookReader: React.FC<BookReaderProps> = ({ outline, chapters, onUpdateChapter, onRegenerateChapter }) => {
  const [currentChapterIndex, setCurrentChapterIndex] = useState(0);
  const [isExporting, setIsExporting] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editContent, setEditContent] = useState('');
  const printRef = useRef<HTMLDivElement>(null);

  const activeChapter = chapters[currentChapterIndex];
  const chapterOutline = outline.chapters[currentChapterIndex];

  const isGenerating = activeChapter?.isGenerating;
  const hasContent = activeChapter && activeChapter.content.length > 0;

  // Reset edit mode when chapter changes
  useEffect(() => {
    setIsEditing(false);
    setEditContent(activeChapter?.content || '');
  }, [currentChapterIndex, activeChapter]);

  const handleSaveEdit = () => {
    onUpdateChapter(currentChapterIndex, editContent);
    setIsEditing(false);
  };

  const handleRegenerateClick = () => {
    if (window.confirm("Are you sure you want to regenerate this chapter? Current content will be lost.")) {
      onRegenerateChapter(currentChapterIndex);
      setIsEditing(false);
    }
  };

  const downloadMarkdown = () => {
    const element = document.createElement("a");
    const content = chapters.map(c => `# ${c.title}\n\n${c.content}\n\n`).join("---\n\n");
    const file = new Blob([`# ${outline.title}\n\n${outline.description}\n\n${content}`], {type: 'text/markdown'});
    element.href = URL.createObjectURL(file);
    element.download = `${outline.title.replace(/\s+/g, '_')}.md`;
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  const handleDownloadPDF = async () => {
    if (!printRef.current) return;
    setIsExporting(true);
    await new Promise(resolve => setTimeout(resolve, 500));

    try {
      const element = printRef.current;
      const opt = {
        margin: [0.5, 0.5, 0.5, 0.5], 
        filename: `${outline.title.replace(/\s+/g, '_')}_Manuscript.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true, logging: false, scrollY: 0 },
        jsPDF: { unit: 'in', format: 'letter', orientation: 'portrait' },
        pagebreak: { mode: ['css', 'legacy'] }
      };
      // @ts-ignore
      await window.html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error("PDF generation failed", err);
      alert("Direct PDF generation encountered an issue. Please use the 'Print' button.");
    } finally {
      setIsExporting(false);
    }
  };

  const handlePrint = () => {
    document.title = outline.title;
    window.print();
  };

  return (
    <>
      {/* --- SCREEN VIEW --- */}
      <div className="h-[calc(100vh-140px)] flex gap-0 border border-slate-200 bg-white shadow-sm rounded-xl overflow-hidden no-print">
        {/* Sidebar TOC */}
        <div className="w-80 hidden lg:flex flex-col bg-slate-50 border-r border-slate-200 shrink-0">
          <div className="p-6 border-b border-slate-200 bg-white">
             <h2 className="font-serif font-bold text-slate-900 truncate leading-tight text-lg">{outline.title}</h2>
             <p className="text-xs text-blue-600 mt-2 uppercase tracking-wider font-bold">Table of Contents</p>
          </div>
          <div className="overflow-y-auto flex-1 p-3 space-y-1">
            {outline.chapters.map((chap, idx) => {
              const chapStatus = chapters.find(c => c.chapterNumber === chap.chapterNumber);
              const isBusy = chapStatus && chapStatus.isGenerating;

              return (
                <button
                  key={chap.chapterNumber}
                  onClick={() => setCurrentChapterIndex(idx)}
                  className={`w-full text-left px-4 py-3 rounded-lg text-sm transition-all flex items-center justify-between group ${
                    idx === currentChapterIndex 
                      ? 'bg-blue-50 text-blue-900 font-bold border border-blue-100 shadow-sm' 
                      : 'text-slate-500 hover:bg-slate-100 hover:text-slate-900 border border-transparent'
                  }`}
                >
                  <div className="truncate">
                    <span className={`block text-[10px] font-bold mb-0.5 uppercase ${idx === currentChapterIndex ? 'text-blue-500' : 'text-slate-400'}`}>Chapter {chap.chapterNumber}</span>
                    <span className="font-serif">{chap.title}</span>
                  </div>
                  {isBusy && <Loader2 size={14} className="animate-spin text-blue-500" />}
                </button>
              );
            })}
          </div>
        </div>

        {/* Main Reading Area */}
        <div className="flex-1 flex flex-col bg-white relative">

          {/* Toolbar */}
          <div className="h-16 border-b border-slate-100 flex items-center justify-between px-8 shrink-0 bg-white/95 backdrop-blur-sm z-10 sticky top-0">
             <span className="text-xs font-bold tracking-[0.2em] text-slate-400 uppercase">
               Chapter {chapterOutline.chapterNumber}
             </span>
             <div className="flex items-center gap-2">
                {!isEditing && !isGenerating && (
                  <>
                    <button onClick={() => setIsEditing(true)} className="p-2 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-50" title="Edit Text">
                      <Edit3 size={18} />
                    </button>
                    <button onClick={handleRegenerateClick} className="p-2 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-50" title="Regenerate Chapter">
                      <RefreshCcw size={18} />
                    </button>
                    <div className="w-px h-4 bg-slate-200 mx-2"></div>
                  </>
                )}
                <button onClick={downloadMarkdown} className="p-2 text-slate-400 hover:text-blue-600 rounded-lg hover:bg-blue-50" title="Download MD"><FileText size={18} /></button>
                <button onClick={handlePrint} className="flex items-center gap-2 px-3 py-2 text-xs font-bold uppercase tracking-wider text-slate-600 hover:bg-slate-50 rounded-md"><Printer size={14} /> Print</button>
                <button onClick={handleDownloadPDF} disabled={isExporting} className="flex items-center gap-2 px-4 py-2 text-xs font-bold uppercase tracking-wider bg-blue-950 text-white hover:bg-blue-900 rounded-md shadow-sm disabled:opacity-50 min-w-[140px] justify-center">
                  {isExporting ? <Loader2 size={14} className="animate-spin"/> : <Download size={14} />}
                  {isExporting ? 'Preparing...' : 'Download PDF'}
                </button>
             </div>
          </div>

          {/* Chapter Content */}
          <div className="flex-1 overflow-y-auto bg-white scroll-smooth relative">
            <div className="max-w-2xl mx-auto px-8 py-16">
              <h1 className="text-4xl md:text-5xl font-serif font-bold text-slate-900 mb-12 leading-tight text-center">
                {chapterOutline.title}
              </h1>

              {isGenerating ? (
                <div className="space-y-8 opacity-50 animate-pulse">
                   <div className="flex flex-col items-center justify-center py-12 text-slate-400 gap-3">
                      <Loader2 className="animate-spin w-6 h-6 text-blue-500" />
                      <p className="font-serif italic text-sm text-blue-500 font-medium">Writing in progress...</p>
                   </div>
                </div>
              ) : isEditing ? (
                <div className="animate-in fade-in">
                   <textarea 
                     value={editContent}
                     onChange={(e) => setEditContent(e.target.value)}
                     className="w-full h-[60vh] p-4 font-serif text-lg leading-loose border-2 border-blue-200 rounded-lg outline-none focus:ring-4 focus:ring-blue-50 resize-y"
                   />
                   <div className="flex justify-end gap-3 mt-4 sticky bottom-4">
                      <button onClick={() => setIsEditing(false)} className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-600 font-bold hover:bg-slate-50 flex items-center gap-2 shadow-sm"><X size={16}/> Cancel</button>
                      <button onClick={handleSaveEdit} className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-500 flex items-center gap-2 shadow-md"><Check size={16}/> Save Changes</button>
                   </div>
                </div>
              ) : hasContent ? (
                <div className="prose prose-lg prose-slate font-serif max-w-none prose-p:indent-0 prose-p:text-justify prose-p:mb-6 prose-headings:font-sans prose-headings:text-blue-950 prose-a:text-blue-600 text-slate-800 leading-loose">
                   <ReactMarkdown>{activeChapter.content}</ReactMarkdown>
                </div>
              ) : (
                 <div className="flex flex-col items-center justify-center h-64 text-slate-300">
                   <FileText size={48} className="mb-4 opacity-20" />
                   <p className="italic font-serif">Waiting for content generation...</p>
                   <button onClick={handleRegenerateClick} className="mt-4 text-blue-600 text-sm font-bold underline">Generate Now</button>
                 </div>
              )}
            </div>
          </div>

          {/* Footer Navigation */}
          <div className="h-16 border-t border-slate-100 bg-slate-50 flex items-center justify-between px-8 shrink-0">
             <button 
               onClick={() => setCurrentChapterIndex(Math.max(0, currentChapterIndex - 1))}
               disabled={currentChapterIndex === 0}
               className="flex items-center gap-2 text-slate-500 hover:text-blue-700 disabled:opacity-20 disabled:cursor-not-allowed font-bold text-xs transition-colors uppercase tracking-wide"
             >
               <ChevronLeft size={16} /> Previous
             </button>

             <span className="text-xs text-slate-400 font-mono">
               {currentChapterIndex + 1} / {outline.chapters.length}
             </span>

             <button 
               onClick={() => setCurrentChapterIndex(Math.min(outline.chapters.length - 1, currentChapterIndex + 1))}
               disabled={currentChapterIndex === outline.chapters.length - 1}
               className="flex items-center gap-2 text-slate-500 hover:text-blue-700 disabled:opacity-20 disabled:cursor-not-allowed font-bold text-xs transition-colors uppercase tracking-wide"
             >
               Next <ChevronRight size={16} />
             </button>
          </div>

        </div>
      </div>

      {/* --- HIDDEN PDF STRUCTURE --- */}
      <div 
        id="print-root" 
        ref={printRef} 
        className={`bg-white text-black font-serif w-full ${isExporting ? 'absolute left-0 top-0 z-[9999] block' : 'hidden'} print:block print:static`}
        style={{ width: isExporting ? '8.5in' : undefined }}
      >
         {/* ... (Existing PDF structure content remains same as previous but needs to handle images if present) ... */}
         <div className="max-w-[8.5in] mx-auto bg-white p-[0.5in] min-h-screen print:p-0 print:max-w-none">
           {/* Cover Page */}
           <div className="min-h-[10in] flex flex-col justify-center items-center text-center px-8 py-24 break-after-page relative border-b-0">
               {outline.coverImage && (
                  <div className="mb-8 w-64 h-64 shadow-lg overflow-hidden mx-auto">
                    <img src={`data:image/jpeg;base64,${outline.coverImage}`} className="w-full h-full object-cover" />
                  </div>
               )}
              <div className="flex-1 flex flex-col justify-center w-full">
                <h1 className="text-5xl md:text-6xl font-bold mb-8 leading-tight text-slate-900">{outline.title}</h1>
