```typescript
import React, { useState, useEffect } from 'react';
import { BookProject, BookSeries, AppView } from './types';
import { Dashboard } from './components/Dashboard';
import { ProjectEditor } from './components/ProjectEditor';
import { SeriesView } from './components/SeriesView';

const App: React.FC = () => {
  const [view, setView] = useState<AppView>(AppView.DASHBOARD);
  const [projects, setProjects] = useState<BookProject[]>([]);
  const [series, setSeries] = useState<BookSeries[]>([]);

  const [activeProjectId, setActiveProjectId] = useState<string | null>(null);
  const [activeSeriesId, setActiveSeriesId] = useState<string | null>(null);

  // Load data
  useEffect(() => {
    try {
      const savedProjects = localStorage.getItem('storyforge_projects');
      if (savedProjects) setProjects(JSON.parse(savedProjects));

      const savedSeries = localStorage.getItem('storyforge_series');
      if (savedSeries) setSeries(JSON.parse(savedSeries));
    } catch (e) {
      console.error("Failed to load data", e);
    }
  }, []);

  // Save data
  useEffect(() => {
    localStorage.setItem('storyforge_projects', JSON.stringify(projects));
  }, [projects]);

  useEffect(() => {
    localStorage.setItem('storyforge_series', JSON.stringify(series));
  }, [series]);

  // --- Project Handlers ---

  const handleCreateProject = () => {
    const newProject: BookProject = {
      id: crypto.randomUUID(),
      title: 'Untitled Manuscript',
      lastModified: Date.now(),
      sources: [],
      outline: null,
      chapters: [],
      currentStep: 0,
    };

    setProjects(prev => [newProject, ...prev]);
    setActiveProjectId(newProject.id);
    setView(AppView.EDITOR);
  };

  const handleCreateBookInSeries = (seriesId: string) => {
    const newProject: BookProject = {
      id: crypto.randomUUID(),
      seriesId: seriesId,
      title: 'Untitled Series Book',
      lastModified: Date.now(),
      sources: [],
      outline: null,
      chapters: [],
      currentStep: 0,
    };

    setProjects(prev => [newProject, ...prev]);
    // Also update the series to include this book ID
    setSeries(prev => prev.map(s => 
      s.id === seriesId ? { ...s, bookIds: [...s.bookIds, newProject.id] } : s
    ));

    setActiveProjectId(newProject.id);
    setView(AppView.EDITOR);
  };

  const handleUpdateProject = (updatedProject: BookProject) => {
    setProjects(prev => prev.map(p => p.id === updatedProject.id ? updatedProject : p));
  };

  const handleDeleteProject = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Are you sure you want to delete this project?')) {
      setProjects(prev => prev.filter(p => p.id !== id));
      // Remove from series if applicable
      setSeries(prev => prev.map(s => ({
         ...s,
         bookIds: s.bookIds.filter(bid => bid !== id)
      })));

      if (activeProjectId === id) {
        setActiveProjectId(null);
        setView(AppView.DASHBOARD);
      }
    }
  };

  const handleSelectProject = (project: BookProject) => {
    setActiveProjectId(project.id);
    setView(AppView.EDITOR);
  };

  // --- Series Handlers ---

  const handleCreateSeries = (title: string) => {
    const newSeries: BookSeries = {
      id: crypto.randomUUID(),
      title: title,
      description: '',
      context: { characters: [], settings: [] },
      bookIds: [],
      lastModified: Date.now()
    };
    setSeries(prev => [newSeries, ...prev]);
    setActiveSeriesId(newSeries.id);
    setView(AppView.SERIES_VIEW);
  };

  const handleUpdateSeries = (updatedSeries: BookSeries) => {
    setSeries(prev => prev.map(s => s.id === updatedSeries.id ? updatedSeries : s));
  };

  const handleSelectSeries = (s: BookSeries) => {
    setActiveSeriesId(s.id);
    setView(AppView.SERIES_VIEW);
  };

  const handleDeleteSeries = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm('Delete this series? This will NOT delete the books, but will remove their association.')) {
       setSeries(prev => prev.filter(s => s.id !== id));
       setProjects(prev => prev.map(p => p.seriesId === id ? { ...p, seriesId: undefined } : p));
       if (activeSeriesId === id) setView(AppView.DASHBOARD);
    }
  };

  const activeProject = projects.find(p => p.id === activeProjectId);
  const activeSeries = series.find(s => s.id === activeSeriesId);
  const projectContextSeries = activeProject?.seriesId ? series.find(s => s.id === activeProject.seriesId) : undefined;

  // View Routing

  if (view === AppView.EDITOR && activeProject) {
    return (
      <ProjectEditor 
        project={activeProject} 
        seriesContext={projectContextSeries?.context}
        onUpdateProject={handleUpdateProject}
        onBack={() => {
            if (activeProject.seriesId) {
                // If it belongs to a series, go back to Series View
                setActiveSeriesId(activeProject.seriesId);
                setView(AppView.SERIES_VIEW);
            } else {
                setView(AppView.DASHBOARD);
            }
        }}
      />
    );
  }

  if (view === AppView.SERIES_VIEW && activeSeries) {
    return (
      <SeriesView 
        series={activeSeries}
        projects={projects}
        onUpdateSeries={handleUpdateSeries}
        onCreateBookInSeries={handleCreateBookInSeries}
        onSelectProject={handleSelectProject}
        onDeleteProject={handleDeleteProject}
        onBack={() => setView(AppView.DASHBOARD)}
      />
    );
  }

  return (
    <Dashboard 
      projects={projects} 
      series={series}
      onCreateProject={handleCreateProject}
      onCreateSeries={handleCreateSeries}
      onSelectProject={handleSelectProject}
      onSelectSeries={handleSelectSeries}
      onDeleteProject={handleDeleteProject}
      onDeleteSeries={handleDeleteSeries}
    />
  );
};

export default App;
